package com.airguard.ai.ml

import org.junit.Assert.*
import org.junit.Test

/**
 * Test vectors for FeatureScaler equivalence with Python sklearn.
 *
 * These vectors are sourced from:
 *   ml_pipeline/experiments/final_audit/test_vectors.json
 *
 * Each vector was generated by:
 *   1. Taking a real sensor reading from the test set (cutoff 2026-06-01).
 *   2. Running it through the Python sklearn StandardScaler.
 *   3. Recording the scaled values.
 *
 * These tests verify that Kotlin FeatureScaler.scale() produces the same
 * scaled values as Python to within float32 tolerance (1e-4).
 *
 * Note: ONNX model inference cannot be tested here (requires Android Context).
 * See InstrumentedOnnxTest for on-device inference equivalence tests.
 *
 * To run: ./gradlew :app:test
 */
class TestVectorEquivalenceTest {

    private val TOLS = 1e-3f  // float32 round-trip tolerance

    // ── Helper ────────────────────────────────────────────────
    private fun assertScaledEquals(
        label: String,
        raw: DoubleArray,
        expectedScaled: FloatArray
    ) {
        val actual = FeatureScaler.scale(raw)
        assertEquals("$label: wrong array size", expectedScaled.size, actual.size)
        for (i in expectedScaled.indices) {
            assertEquals(
                "$label: feature[$i] (${FeatureScaler.FEATURE_NAMES[i]})",
                expectedScaled[i], actual[i], TOLS
            )
        }
    }

    // ── GOOD sample (test_vectors.json index 0) ───────────────
    // Raw: temp=33.2, hum=71.5, pres=1006.2, gas=30.9, alt=58.8, dp=27.5, hi=42.5
    // Python scaled: [0.1892, 0.8745, 0.5941, -2.4914, -0.5960, 0.4438, 0.4057]
    @Test
    fun scalerEquivalence_GOOD() {
        assertScaledEquals(
            "GOOD sample",
            doubleArrayOf(33.2, 71.5, 1006.2, 30.9, 58.8, 27.5, 42.5),
            floatArrayOf(0.1892f, 0.8745f, 0.5941f, -2.4914f, -0.5960f, 0.4438f, 0.4057f)
        )
    }

    // ── MODERATE sample ───────────────────────────────────────
    // Raw: temp=33.1, hum=70.3, pres=1006.2, gas=58.5, alt=58.5, dp=27.2, hi=41.9
    // Python scaled: [0.1654, 0.7123, 0.5941, -2.1832, -0.6019, 0.3807, 0.3282]
    @Test
    fun scalerEquivalence_MODERATE() {
        assertScaledEquals(
            "MODERATE sample",
            doubleArrayOf(33.1, 70.3, 1006.2, 58.5, 58.5, 27.2, 41.9),
            floatArrayOf(0.1654f, 0.7123f, 0.5941f, -2.1832f, -0.6019f, 0.3807f, 0.3282f)
        )
    }

    // ── UNHEALTHY_SENSITIVE sample ────────────────────────────
    // Raw: temp=33.4, hum=69.4, pres=1006.2, gas=114.4, alt=58.5, dp=27.2, hi=42.0
    // Python scaled: [0.2368, 0.5906, 0.5941, -1.5589, -0.6019, 0.3807, 0.3411]
    @Test
    fun scalerEquivalence_UNHEALTHY_SENSITIVE() {
        assertScaledEquals(
            "UNHEALTHY_SENSITIVE sample",
            doubleArrayOf(33.4, 69.4, 1006.2, 114.4, 58.5, 27.2, 42.0),
            floatArrayOf(0.2368f, 0.5906f, 0.5941f, -1.5589f, -0.6019f, 0.3807f, 0.3411f)
        )
    }

    // ── UNHEALTHY sample ──────────────────────────────────────
    // Raw: temp=33.9, hum=67.7, pres=1006.2, gas=204.5, alt=58.6, dp=27.5, hi=42.5
    // Python scaled: [0.3557, 0.3608, 0.5941, -0.5527, -0.6000, 0.4438, 0.4057]
    @Test
    fun scalerEquivalence_UNHEALTHY() {
        assertScaledEquals(
            "UNHEALTHY sample",
            doubleArrayOf(33.9, 67.7, 1006.2, 204.5, 58.6, 27.5, 42.5),
            floatArrayOf(0.3557f, 0.3608f, 0.5941f, -0.5527f, -0.6000f, 0.4438f, 0.4057f)
        )
    }

    // ── HAZARDOUS sample (pred=UNHEALTHY per Python model) ────
    // Raw: temp=31.5, hum=52.8, pres=996.0, gas=478.1, alt=144.6, dp=22.0, hi=33.8
    // Python scaled: [-0.2150, -1.6533, -1.1085, 2.5027, 1.1086, -0.7121, -0.7184]
    // Python prediction: UNHEALTHY (HAZ missed — 49.2% recall limitation)
    @Test
    fun scalerEquivalence_HAZARDOUS_input() {
        assertScaledEquals(
            "HAZARDOUS input (pred=UNHEALTHY)",
            doubleArrayOf(31.5, 52.8, 996.0, 478.1, 144.6, 22.0, 33.8),
            floatArrayOf(-0.2150f, -1.6533f, -1.1085f, 2.5027f, 1.1086f, -0.7121f, -0.7184f)
        )
    }

    // ── Feature name guard ────────────────────────────────────
    @Test
    fun featureOrderIsCorrect() {
        val names = FeatureScaler.FEATURE_NAMES
        assertTrue(names[0].contains("Temperature", ignoreCase = true))
        assertTrue(names[1].contains("Humidity",    ignoreCase = true))
        assertTrue(names[2].contains("Pressure",    ignoreCase = true))
        assertTrue(names[3].contains("Gas",         ignoreCase = true))
        assertTrue(names[4].contains("Altitude",    ignoreCase = true))
        assertTrue(names[5].contains("Dew",         ignoreCase = true))
        assertTrue(names[6].contains("Heat",        ignoreCase = true))
        // AQI must not appear
        for (name in names) {
            assertFalse("AQI must not be a feature: $name",
                name.contains("AQI", ignoreCase = true))
        }
    }
}
